<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        body {
            font-family: 'Times New Roman', serif;
            margin: 0.5in;
            line-height: 1.3;
            font-size: 12pt;
        }
        .header {
            text-align: center;
            margin-bottom: 0.3in;
            font-weight: bold;
            font-size: 14pt;
        }
        .subheader {
            text-align: center;
            margin-bottom: 0.4in;
        }
        .section {
            margin-top: 0.4in;
            margin-bottom: 0.15in;
            font-weight: bold;
            text-decoration: underline;
        }
        .title {
            font-size: 14pt;
            font-weight: bold;
            text-align: center;
            margin: 0.6in 0 0.4in;
        }
        .body {
            text-align: justify;
            text-indent: 0.3in;
            margin-bottom: 0.2in;
        }
        .indent {
            text-indent: 0.3in;
        }
        .center {
            text-align: center;
        }
        .small {
            font-size: 10pt;
        }
        .placeholder {
            border: 1px solid #000;
            padding: 10px;
            margin: 0.3in 0;
            width: 100%;
            text-align: center;
            font-style: italic;
            color: #666;
        }
        ul, ol {
            margin-left: 0.5in;
        }
    </style>
</head>
<body>
    <div class="header">
        [Header text or logo placeholder]
    </div>

    <div class="subheader">
        [Document subtitle or date]
    </div>

    <div class="section">
        Section 1: Title
    </div>

    <div class="title">
        [Main title: centered, bold, larger font]
    </div>

    <div class="body">
        [First paragraph text - justified, indented]
        <br><br>
        [Second paragraph text - justified, indented]
    </div>

    <div class="section">
        Section 2: Body Content
    </div>

    <div class="body">
        [Paragraph 2 text]
        <br><br>
        [Paragraph 3 text with [illegible] if present]
    </div>

    <div class="placeholder">
        [Diagram: centered box]
    </div>

    <div class="body">
        [Continued text after placeholder]
    </div>

    <div class="center">
        [Centered text or equation: $x = y$]
    </div>

    <div class="body">
        [Paragraph with list]
        <ul>
            <li>Item 1</li>
            <li>Item 2 [illegible]</li>
        </ul>
    </div>

    <div class="section">
        [Footer or closing text]
    </div>

    <div class="small">
        [Small print / copyright / page number]
    </div>
</body>
</html>
